def check(images,p):
 by={f['anim']:(f,images[f['output']]) for f in p['files']};ret={};wholes=[]
 for l,wlo,whi,hlo,hhi in [(1,16,18,26,28),(2,20,22,30,34)]:
  n='searchlight'+('' if l==1 else '_'+str(l));f,a=by[n];_,fire=by[n+'_fire'];_,wreck=by[n+'_wreck'];b=a.getbbox();wholes.append(a);ret[n+'_whole_dimensions']=wlo<=b[2]-b[0]<=whi and hlo<=b[3]-b[1]<=hhi;ret[n+'_wreck_inside_whole']=wreck.getbbox()[0]>=b[0] and wreck.getbbox()[2]<=b[2];x,y=f['points']['light_xy'];rect=[x-3,y-4,x+4,y+5];diff=[(xx,yy) for yy in range(48) for xx in range(32) if a.getpixel((xx,yy))!=fire.getpixel((xx,yy)) and not (rect[0]<=xx<rect[2] and rect[1]<=yy<rect[3])];ret[n+'_only_lens_changes']=not diff;ret[n+'_changed_pixels_outside_lens']=len(diff);fs=[t for name,(t,im) in by.items() if name in [n,n+'_hurt',n+'_fire',n+'_wreck']];ret[n+'_one_source_scale']=len({t['source'] for t in fs})==1 and len({t['recipe']['content_scale'] for t in fs})==1
 ret['level1_level2_differs80']=sum(a!=b for a,b in zip(wholes[0].get_flattened_data(),wholes[1].get_flattened_data()))>=80;ret['eight_distinct_states']=len({im.tobytes() for f,im in by.values()})==8;ret['no_muzzles']=all(not any(k.startswith('muzzle') for k in f['points']) for f in p['files']);return ret
